"""Import the owner's native Quest Dungeons export without changing its art."""
import argparse,hashlib,json,shutil,zipfile
from pathlib import Path
from PIL import Image
from io import BytesIO
ROOT=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('archive',type=Path);args=p.parse_args()
dest=ROOT/'assets/quest-dungeons';dest.mkdir(exist_ok=True)
with zipfile.ZipFile(args.archive) as z:
 meta=json.loads(z.read('map.json'));manifest=json.loads(z.read('objects/manifest.json'));grid=json.loads((dest/'terrain.json').read_text())
 cfg=meta['mapConfig'];tile=cfg['tileSize'];bounds=cfg['boundingBox'];width=cfg['dimensions']['pixelWidth'];height=cfg['dimensions']['pixelHeight']
 assert meta['mapId']==grid['mapId'] and tile==64 and (bounds['minX'],bounds['minY'])==(-2,-7)
 assert len(grid['rows'])==26 and all(len(r)==29 for r in grid['rows']) and sum(c!='.' for r in grid['rows'] for c in r)==562
 raw=z.read('map-composite.png');assert Image.open(BytesIO(raw)).size==(width,height)
 (dest/'map.png').write_bytes(raw)
 (dest/'source-map.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 (dest/'source-objects.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 props=[];unique={};(dest/'objects').mkdir(exist_ok=True)
 def normalized(box):return {'x':box['x']-bounds['minX']*tile,'y':box['y']-bounds['minY']*tile,'w':box['width'],'h':box['height']}
 for o in manifest['objects']:
  if not o.get('visible',True):continue
  sprite=z.read('objects/'+o['filename']);digest=hashlib.sha256(sprite).hexdigest()
  if digest not in unique:
   unique[digest]='objects/'+o['id']+'.png';(dest/unique[digest]).write_bytes(sprite)
  props.append({'id':o['id'],'layer':o['layer'],'bounds':normalized(o['boundingBox']),'foot':normalized(o['groundBounds']),'url':'assets/quest-dungeons/'+unique[digest]})
 chest=next(o for o in props if o['id']=='40420c70-1e86-493e-a829-79b42d260c18')
 data={'id':'quest-dungeons','sourceId':meta['mapId'],'sourceOrigin':{'x':-2,'y':-7},'tile':tile,'width':width,'height':height,'rows':grid['rows'],'props':props,'chest':chest,'spawn':{'x':928,'y':1440},'enemySpawn':{'x':928,'y':672}}
 (ROOT/'quest-dungeons-data.js').write_text("'use strict';\n/* Native owner export; generated by tools/import_quest_dungeons.py. */\nglobalThis.MareQuestDungeonData="+json.dumps(data,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
 (dest/'provenance.json').write_text(json.dumps({'mapId':meta['mapId'],'archiveSha256':hashlib.sha256(args.archive.read_bytes()).hexdigest(),'compositeSha256':hashlib.sha256(raw).hexdigest(),'dimensions':[width,height],'objects':len(props),'uniqueSprites':len(unique),'terrainSource':grid['source'],'artProcessing':'Native composite and object RGBA files copied byte-for-byte; only world origins normalized. No map generation, repaint or moved source objects.','chestSourcePixels':[802,-168],'chestNormalizedBounds':chest['bounds'],'sourceOriginPixels':[-128,-448],'spawnSourceCell':[12,15]},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 print('Imported',len(props),'objects;',len(unique),'unique original images; chest',chest['bounds'])
